replace_once('tests/test_fusion.py', 'np.testing.assert_allclose(result.point_covariance[0, 0, 0], expected, rtol=2e-6, atol=2e-6)\n', 'np.testing.assert_allclose(result.point_covariance[0, 0, 0], expected, rtol=2e-6, atol=2e-6)\n\n\n\ndef test_covariance_intersection_fusion_is_invariant_to_window_input_order() -> None:\n    windows = [\n        make_window("window-c", [0, 1], 0.25),\n        make_window("window-a", [0, 1], -0.10),\n        make_window("window-b", [0, 1], 0.05),\n    ]\n    gauges = {window.window_id: Sim3.identity() for window in windows}\n    uncertainties = {\n        "window-a": make_uncertainty(windows[1], 0.8),\n        "window-b": make_uncertainty(windows[2], 1.2),\n        "window-c": make_uncertainty(windows[0], 2.0),\n    }\n\n    reference = fuse_windows(\n        windows,\n        gauges,\n        uncertainties,\n        method="covariance_intersection",\n    )\n    for ordering in permutations(windows):\n        candidate = fuse_windows(\n            list(ordering),\n            gauges,\n            uncertainties,\n            method="covariance_intersection",\n        )\n        np.testing.assert_array_equal(candidate.frame_indices, reference.frame_indices)\n        np.testing.assert_array_equal(candidate.valid_mask, reference.valid_mask)\n        np.testing.assert_array_equal(candidate.contributors, reference.contributors)\n        np.testing.assert_allclose(candidate.point_map, reference.point_map)\n        np.testing.assert_allclose(\n            candidate.point_covariance,\n            reference.point_covariance,\n        )\n')

replace_once('docs/observation-belief-export.md', '  --pixel-stride 4 \\\n  --max-gauge-rank 64 \\\n', '  --pixel-stride 4 \\\n  --sampling-mode information_stratified \\\n  --max-gauge-rank 64 \\\n')

replace_once('docs/observation-belief-export.md', 'The export fails when that revision cannot be\nobtained from the checkout and is not provided explicitly.\n', 'The export fails when that revision cannot be\nobtained from the checkout and is not provided explicitly.\n\n`fixed_grid` sampling remains available to reproduce frozen artifacts.\n`information_stratified` partitions each frame into `pixel_stride` tiles and\nselects at most one valid row per tile using a deterministic score combining\nsource reliability, depth leverage, and conditional precision. This avoids\ndropping an otherwise valid tile merely because its upper-left grid pixel is\ninvalid. The selected mode is content-addressed metadata.\n')

replace_once('docs/observation-belief-export.md', 'A deterministic eigendecomposition produces a shared covariance root. The\nexport fails when `--max-gauge-rank` would retain less than\n`--minimum-retained-gauge-trace` of the joint covariance trace. Rank reduction is\ntherefore explicit and auditable rather than a silent memory optimization.\n', "A deterministic eigendecomposition produces a shared covariance root. Before\ntruncation, each window's log-scale and rotation coordinates are normalized by a\nrobust representative metric point radius; translation already has displacement\nunits. The retained trace is therefore an observation-displacement proxy rather\nthan a raw sum of squared radians, metres, and dimensionless log scale. It is\ninvariant to expressing the same metric geometry in metres or millimetres. The\nexport fails when `--max-gauge-rank` would retain less than\n`--minimum-retained-gauge-trace` under this declared metric. Rank reduction is\ntherefore explicit and auditable rather than a silent memory optimization.\n")

replace_once('docs/observation-belief-export.md', 'time. `group_composite_weight` separately caps dense duplicate information.\n', 'time. `group_composite_weight` is the final per-row generalized-Bayes power\nthat caps dense duplicate information. The artifact declares\n`group_composite_weight_semantics = final-per-row-effective-sample-cap-v1`;\ndownstream consumers must not apply a second effective-sample cap to those rows.\nPer-group raw-row, unique-entity, effective-sample, and per-row-weight statistics\nare embedded for audit.\n')

replace_once('docs/experiment-protocol.md', 'Production runs optimize one weight per overlapping frame from a\nrepresentative covariance sample. Pointwise CI weights remain available as an\nexplicit small-scale diagnostic.\n', 'Production runs optimize one weight per overlapping frame from a\nrepresentative covariance sample. Pointwise CI weights remain available as an\nexplicit small-scale diagnostic. The sequential pairwise implementation processes\nwindows in a canonical `(start, stop, window_id)` order, so the public fusion\nresult is invariant to caller list order. This is not a claim of generalized\nmultiway CI; the unfused factor interface remains the preferred downstream\nBayesian representation.\n')


